const handleHomeVenueSelect = async () => {
  if (!selectedHomeSize) return;

  const venueData: VenueData = {
    name: 'Home Venue',
    address: 'Your Home',
    rating: 5,
    distance: '0 miles',
    type: 'home',
    partySize: selectedHomeSize,
    addOns: selectedHomeAddOns
  };

  setSelectedVenue(venueData);
  console.log('Home venue selected:', venueData);

  // Save home venue selection to database
  if (currentPartyId && currentUser) {
    try {
      const response = await fetch('/api/party-venue', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          partyId: currentPartyId,
          userId: currentUser.id,
          venue: venueData,
          isCustom: true
        })
      });

      if (response.ok) {
        console.log('Home venue selection saved to database');
      } else {
        console.error('Failed to save home venue selection');
      }
    } catch (error) {
      console.error('Error saving home venue selection:', error);
    }
  }

  // Update local party data
  if (partyData) {
    const updatedPartyData: PartyData = {
      ...partyData,
      venue: venueData
    };

    setPartyData(updatedPartyData);
    console.log('Home venue automatically added to party');
  }
};

